//! Renderers for structurally significant files: pubspecs, barrels, the
//! conditional-import groups, the cross-file inheritance chain and factory
//! redirect, part/part-of pairs, the app entry point, and the `tests/` files.

use super::RenderCtx;
use crate::coverage::Cell;
use crate::plan::{Layout, PackageId, VENDORED_PACKAGES, feature_dir_counts, ladder_version};
use std::fmt::Write as _;

pub(super) fn root_pubspec(w: &mut String, ctx: &mut RenderCtx<'_>) {
    dw!(
        w,
        "# Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    dw!(w, "name: app\n");
    dw!(
        w,
        "description: Application package of the generated dartq stress corpus.\n"
    );
    dw!(w, "version: 1.0.0\n");
    dw!(w, "publish_to: none\n\n");
    // The workspace root must sit at >= 3.5 for the `workspace:` key to be
    // pub-valid (the nested-versions corpus documents the >= 3.5 gate).
    let sdk = if ctx.plan.layout == Layout::Workspace {
        "^3.15.0"
    } else {
        "^3.13.0"
    };
    dw!(w, "environment:\n  sdk: {sdk}\n\n");
    if ctx.plan.layout == Layout::Workspace {
        dw!(w, "workspace:\n  - packages/core\n");
        for i in 0..ctx.plan.packages {
            dw!(w, "  - {}\n", ctx.plan.feature_root(i));
        }
        dw!(w, "\n");
    }
    dw!(w, "dependencies:\n");
    if ctx.plan.layout == Layout::Workspace {
        // Workspace members are declared with plain version constraints —
        // pub canonicalizes them onto the workspace root.
        dw!(w, "  core: ^1.0.0\n");
        for i in 0..ctx.plan.packages {
            dw!(w, "  feature_{i:04}: ^1.0.0\n");
        }
        for (name, _) in VENDORED_PACKAGES {
            dw!(w, "  {name}:\n    path: third_party/{name}\n");
        }
    } else {
        dw!(w, "  core:\n    path: packages/core\n");
        let import_count = (ctx.plan.packages as usize).min(12);
        for i in 0..import_count {
            dw!(w, "  feature_{i:04}:\n    path: packages/feature_{i:04}\n");
        }
    }
    if ctx.plan.flutter_app {
        // #2063: the flutter stub rides alongside the vendored path deps —
        // a plain path package in both layouts (never a workspace member).
        dw!(w, "  flutter:\n    path: packages/flutter\n");
    }
    if ctx.plan.layout == Layout::Workspace {
        ctx.coverage.hit(Cell::WorkspaceLayout);
    }
}

pub(super) fn package_pubspec(w: &mut String, ctx: &mut RenderCtx<'_>, package: PackageId) {
    dw!(
        w,
        "# Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    let name = package.name();
    dw!(w, "name: {name}\n");
    match package {
        PackageId::Core => {
            dw!(
                w,
                "description: Shared core package of the generated dartq stress corpus.\n"
            );
        }
        PackageId::Feature(p) => {
            dw!(
                w,
                "description: Feature package {p:04} of the generated dartq stress corpus.\n"
            );
        }
    }
    dw!(w, "version: 1.0.0\n");
    dw!(w, "publish_to: none\n\n");
    let sdk = match package {
        PackageId::Core => ctx.plan.core_sdk_constraint(),
        PackageId::Feature(p) => ctx.plan.feature_sdk_constraint(p),
    };
    dw!(w, "environment:\n  sdk: {sdk}\n\n");
    let workspace = ctx.plan.layout == Layout::Workspace;
    if workspace {
        dw!(w, "resolution: workspace\n\n");
        ctx.coverage.hit(Cell::WorkspaceLayout);
    }
    if let PackageId::Feature(p) = package {
        if workspace {
            // Members depend on siblings with plain constraints; the shared
            // resolution maps them. The version ladder additionally wires
            // one vendored path dep per member for the mixed face.
            dw!(w, "dependencies:\n  core: ^1.0.0\n");
            if ctx.plan.flutter_app {
                // #2063: the flutter stub is a path dep like the vendored
                // packages, resolved relative to the member's depth.
                let rel = "../".repeat(ctx.plan.feature_depth(p) - 1);
                dw!(w, "  flutter:\n    path: {rel}flutter\n");
            }
            if ctx.plan.version_ladder {
                let (name, _) = VENDORED_PACKAGES[p as usize % VENDORED_PACKAGES.len()];
                let rel = "../".repeat(ctx.plan.feature_depth(p));
                dw!(w, "  {name}:\n    path: {rel}third_party/{name}\n");
            }
        } else {
            dw!(w, "dependencies:\n  core:\n    path: ../core\n");
            if ctx.plan.flutter_app {
                // #2063: widget-bearing packages import the stub surface.
                dw!(w, "  flutter:\n    path: ../flutter\n");
            }
        }
    }
}

pub(super) fn main_entry(w: &mut String, ctx: &mut RenderCtx<'_>) {
    let import_count = (ctx.plan.packages as usize).min(12);
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    dw!(
        w,
        "import 'package:core/core.dart' deferred as core_lazy;\n"
    );
    dw!(w, "import 'package:core/core.dart';\n");
    for i in 0..import_count {
        dw!(w, "import 'package:feature_{i:04}/feature_{i:04}.dart';\n");
    }
    dw!(w, "import 'src/controllers/controller_00000.dart';\n");
    dw!(w, "import 'src/screens/screen_00000.dart';\n\n");
    dw!(
        w,
        "/// Application entry point wiring the generated packages together.\n"
    );
    dw!(
        w,
        "Future<void> main() async {{\n  await core_lazy.loadLibrary();\n\n  final shared = core_lazy.CoreValue(1);\n  final product = ProductLine0('sku-1');\n  final report = core_lazy.LazyReport('boot');\n\n  final state = <String, int>{{\n    'shared': shared.id,\n    'product': product.sku.length,\n    'report': report.payload.length,\n  }};\n\n  final mode = switch (state.length) {{\n    0 => 'empty',\n    1 || 2 => 'small',\n    _ => 'ready',\n  }};\n}}\n"
    );
    ctx.coverage.hit(Cell::PackageUriImport);
    ctx.coverage.hit(Cell::DeferredImport);
}

