pub(super) fn chain_link(w: &mut String, ctx: &mut RenderCtx<'_>, index: usize) {
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n\n"
    );
    if index == 0 {
        dw!(w, "/// Root of the cross-file inheritance chain.\n");
        dw!(w, "class ChainNode0 {{\n  int depth() => 0;\n}}\n");
    } else {
        dw!(w, "import 'chain_link_{}.dart';\n\n", index - 1);
        dw!(
            w,
            "/// Link {} of the cross-file inheritance chain.\n",
            index
        );
        dw!(
            w,
            "class ChainNode{index} extends ChainNode{} {{\n  @override\n  int depth() => {} + super.depth();\n}}\n",
            index - 1,
            index
        );
    }
    ctx.coverage.hit(Cell::InheritanceDeep);
}

