/// Statement blocks rotated through the `tests/` files. The test-framework
/// wrapper is gone (`package:test` is absent from the materialized package
/// config, and pinning a pub-cache path would break determinism): each block
/// is an immediately-invoked closure that exercises the same pattern and
/// expression surface, with `expect(a, b)` demoted to `assert(a == b)` and
/// `fail` to `throw StateError`. Only `dart:core` builtins are referenced, so
/// the files analyze without a single undefined symbol.
const TEST_BLOCKS: [&str; 10] = [
    "  // named record pattern\n  () {\n    final (:width, :height) = (width: 3, height: 4);\n    assert(width * height == 12);\n  }();\n",
    "  // positional record pattern\n  () {\n    final (a, b) = (7, 8);\n    assert(a + b == 15);\n  }();\n",
    "  // list pattern in if-case\n  () {\n    final values = <int>[1, 2, 3, 4];\n    if (values case [var first, var second, ...var rest]) {\n      assert(first + second == 3);\n      assert(rest.length == 2);\n    } else {\n      throw StateError('pattern should match');\n    }\n  }();\n",
    "  // map pattern in switch\n  () {\n    const value = <String, int>{'b': 2};\n    final label = switch (value) {\n      {'a': int a} => 'a:$a',\n      {'b': int b} => 'b:$b',\n      _ => 'other',\n    };\n    assert(label == 'b:2');\n  }();\n",
    "  // collection control flow\n  () {\n    final values = <int>[\n      for (var i = 0; i < 5; i++)\n        if (i.isEven) i,\n      ...[7, 8],\n    ];\n    assert(values.length == 5);\n  }();\n",
    "  // relational switch expression\n  () {\n    final label = switch (9) {\n      > 8 => 'high',\n      _ => 'low',\n    };\n    assert(label == 'high');\n  }();\n",
    "  // null safety fallback\n  () {\n    String? maybe;\n    assert((maybe ?? 'fallback') == 'fallback');\n  }();\n",
    "  // cascade\n  () {\n    final buffer = StringBuffer()\n      ..write('a')\n      ..write('b');\n    assert(buffer.toString() == 'ab');\n  }();\n",
    "  // numeric literals\n  () {\n    assert(0xFF == 255);\n    final scaled = 1.5e2 + 0x10;\n    assert(scaled == 166);\n  }();\n",
    "  // string interpolation\n  () {\n    final tag = 'v${1 + 1}';\n    final label = 'value-$tag end';\n    assert(label == 'value-v2 end');\n  }();\n",
];

pub(super) fn test_file(w: &mut String, ctx: &mut RenderCtx<'_>, ordinal: usize) {
    let feature = ordinal % ctx.plan.packages as usize;
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    dw!(w, "import 'package:core/core.dart';\n");
    dw!(
        w,
        "import 'package:feature_{feature:04}/feature_{feature:04}.dart';\n\n"
    );
    dw!(w, "void main() {{\n");
    for j in 0..4 {
        let pick = (ordinal * 3 + j * 7) % TEST_BLOCKS.len();
        w.push_str(TEST_BLOCKS[pick]);
    }
    dw!(w, "}}\n");
    ctx.coverage.hit(Cell::PackageUriImport);
}

// --- 1d: version-ladder faces -------------------------------------------------

/// `<member>/.dart_tool/pub/workspace_ref.json` — `{"workspaceRoot": rel}`
/// pointing back at the tree root with `depth` `..` segments (1e). Shape
/// pinned by the nested-versions corpus.
pub(super) fn workspace_ref(w: &mut String, ctx: &mut RenderCtx<'_>, depth: usize) {
    let rel = "../".repeat(depth);
    let rel = rel.trim_end_matches('/');
    dw!(w, "{{\n  \"workspaceRoot\": \"{rel}\"\n}}\n");
    ctx.coverage.hit(Cell::WorkspaceLayout);
}

/// Root `.dart_tool/package_config.json` — the hand-written shared
/// resolution (1e): every workspace member plus every vendored package, in
/// pub's output shape (`name`/`rootUri`/`packageUri`/`languageVersion`,
/// `languageVersion` = the package's settled version = the lower bound of
/// its sdk constraint). Entries are emitted in lexicographic name order —
/// the same shape pub writes (nested-versions corpus ground truth).
pub(super) fn root_package_config(w: &mut String, ctx: &mut RenderCtx<'_>) {
    let mut entries: Vec<(String, String, String)> = Vec::new();
    for (name, constraint) in VENDORED_PACKAGES {
        entries.push((
            (*name).to_string(),
            format!("../third_party/{name}"),
            ladder_version(constraint).to_string(),
        ));
    }
    entries.push((
        "app".to_string(),
        "../".to_string(),
        "3.15".to_string(), // root pubspec sdk ^3.15.0 -> 3.15
    ));
    entries.push(("core".to_string(), "../packages/core".to_string(), {
        ctx.plan.core_language_version().to_string()
    }));
    for i in 0..ctx.plan.packages {
        entries.push((
            format!("feature_{i:04}"),
            format!("../{}", ctx.plan.feature_root(i)),
            ctx.plan.feature_language_version(i).to_string(),
        ));
    }
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    w.push_str("{\n  \"configVersion\": 2,\n  \"packages\": [\n");
    for (i, (name, root_uri, version)) in entries.iter().enumerate() {
        let comma = if i + 1 < entries.len() { "," } else { "" };
        dw!(
            w,
            "    {{\n      \"name\": \"{name}\",\n      \"rootUri\": \"{root_uri}\",\n      \"packageUri\": \"lib/\",\n      \"languageVersion\": \"{version}\"\n    }}{comma}\n"
        );
    }
    w.push_str("  ]\n}\n");
    ctx.coverage.hit(Cell::WorkspaceLayout);
}

/// `third_party/<name>/pubspec.yaml` — vendored path dep, never a workspace
/// member (1e). Its sdk constraint is its `VENDORED_PACKAGES` entry's ladder
/// rung; `index` addresses the SORTED name table the iterator walks, so the
/// emitted constraint follows the name, not the table position.
pub(super) fn vendored_pubspec(w: &mut String, index: u32) {
    let mut vendored: Vec<(&str, &str)> = VENDORED_PACKAGES.to_vec();
    vendored.sort_unstable_by(|a, b| a.0.cmp(b.0));
    let (name, constraint) = vendored[index as usize];
    dw!(
        w,
        "# Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    dw!(w, "name: {name}\n");
    dw!(
        w,
        "description: Vendored non-member package of the generated dartq stress corpus.\n"
    );
    dw!(w, "version: 1.0.0\n");
    dw!(w, "publish_to: none\n\n");
    dw!(w, "environment:\n  sdk: {constraint}\n");
}

/// `third_party/<name>/lib/<name>.dart` (1e): a minimal library carrying a
/// `// @dart =` banner at its own settled version — the same-version
/// baseline face.
pub(super) fn vendored_lib(w: &mut String, index: u32) {
    let mut vendored: Vec<(&str, &str)> = VENDORED_PACKAGES.to_vec();
    vendored.sort_unstable_by(|a, b| a.0.cmp(b.0));
    let (name, constraint) = vendored[index as usize];
    let version = ladder_version(constraint);
    dw!(w, "// @dart = {version}\n");
    dw!(
        w,
        "// Generated by corpus-gen. Deterministic corpus; do not edit.\n\n"
    );
    dw!(
        w,
        "/// Vendored library pinned at language version {version}.\n"
    );
    dw!(
        w,
        "class {} {{\n  const {}();\n\n  String tag() => '{name}-{version}';\n}}\n",
        crate::emit::vendored_type_name(name),
        crate::emit::vendored_type_name(name),
    );
}

/// `analysis_options.yaml` for a feature/core package (1d): the
/// `enable-experiment` manifest face — two catalog experiments rotating by
/// package index, exactly the shape the analyzer reads.
pub(super) fn package_analysis_options(
    w: &mut String,
    ctx: &mut RenderCtx<'_>,
    package: PackageId,
) {
    let index = match package {
        PackageId::Core => 0usize,
        PackageId::Feature(p) => (p as usize) + 1,
    };
    analysis_options(w, ctx, index);
}

/// Root `analysis_options.yaml` — the app package's entry of the
/// enable-experiment face (1d), slot `packages + 1` of the catalog rotation.
pub(super) fn root_analysis_options(w: &mut String, ctx: &mut RenderCtx<'_>) {
    analysis_options(w, ctx, ctx.plan.packages as usize + 1);
}

fn analysis_options(w: &mut String, ctx: &mut RenderCtx<'_>, index: usize) {
    dw!(
        w,
        "# Generated by corpus-gen. Deterministic corpus; do not edit.\n"
    );
    let [first, second] = ctx.plan.package_experiments(index);
    dw!(
        w,
        "analyzer:\n  enable-experiment:\n    - {first}\n    - {second}\n"
    );
    ctx.coverage.hit(Cell::EnableExperiment);
}
